  int16_t *sharpened_image = malloc(width * height * sizeof(int16_t));
  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      int16_t sum = 0;
      for (int dy = -1; dy <= 1; dy++) {
